import{F as e,I as t,L as n,M as r,R as i,et as a,n as o}from"./chunks/framework.Bs4wm_X5.js";import{d as s}from"./chunks/theme.DtloWbYQ.js";import{vr as c}from"./chunks/assets.BpWoSz4B.js";var l=JSON.parse(`{"title":"Intervals","description":"Different kinds of relations between two notes","frontmatter":{"title":"Intervals","description":"Different kinds of relations between two notes","cover":"guang-yang.jpg","date":"2021-09-15T00:00:00.000Z"},"headers":[],"relativePath":"theory/intervals/index.md","filePath":"theory/intervals/index.md","lastUpdated":1790102922000}`),u={name:`theory/intervals/index.md`};function d(o,l,u,d,f,p){let m=s;return a(),e(`div`,null,[l[0]||=t(`<p><img src="`+c+`" alt="svg" width="312" height="312"></p><p>Two notes sounding simultaneously or sequentially form the basic building block for all the emotional expressiveness of music. They form some kind of relationships that bring up some distinct feeling.</p><p>The most basic is the 1:2 ratio of an <a href="./unison-octave/">Unison and octave</a>, that are foundational for cyclic nature of pitch class space. <a href="./fifth-fourth/">Perfect Fifth and Fourth</a> are the foundational consonances that bring joy of the simple 2:3 and 3:4 ratios. This is the root of the 12 note system as a whole.</p><p><a href="./third-sixth/">Thirds and Sixth</a> are the imperfect consonances to evoke deeper feelings while the <a href="./second-seventh/">Seconds and Sevenths</a> are the sharper dissonances to spice everything up. We&#39;ll explore the process of the <a href="./emancipation/">Emancipation of dissonance</a> to find out how did we get at this point in our pitch pairs interpretation. And take a brief look at some mathematical implications of building <a href="./cycles/">interval chains</a>.</p>`,4),i(m,{video:`3sUpoSTy8zw`}),i(m,{video:`cyW5z-M2yzw`}),l[1]||=r(`h2`,{id:`pitch-class-space`,tabindex:`-1`},[n(`Pitch class space `),r(`a`,{class:`header-anchor`,href:`#pitch-class-space`,"aria-label":`Permalink to “Pitch class space”`},`​`)],-1),l[2]||=r(`p`,null,`In music theory, pitch-class space is the circular space representing all the notes (pitch classes) in a musical octave. In this space, there is no distinction between tones that are separated by an integral number of octaves. For example, C4, C5, and C6, though different pitches, are represented by the same point in pitch class space.`,-1),l[3]||=r(`p`,null,`Since pitch-class space is a circle, we return to our starting point by taking a series of steps in the same direction: beginning with C, we can move "upward" in pitch-class space, through the pitch classes C♯, D, D♯, E, F, F♯, G, G♯, A, A♯, and B, returning finally to C. By contrast, pitch space is a linear space: the more steps we take in a single direction, the further we get from our starting point.`,-1),l[4]||=r(`p`,null,`Deutsch and Feroe (1981), and Lerdahl and Jackendoff (1983) use a "reductional format" to represent the perception of pitch-class relations in tonal contexts. These two-dimensional models resemble bar graphs, using height to represent a pitch class's degree of importance or centricity. Lerdahl's version uses five levels: the first (highest) contains only the tonic, the second contains tonic and dominant, the third contains tonic, mediant, and dominant, the fourth contains all the notes of the diatonic scale, and the fifth contains the chromatic scale. In addition to representing centricity or importance, the individual levels are also supposed to represent "alphabets" that describe the melodic possibilities in tonal music (Lerdahl 2001, 44–46). The model asserts that tonal melodies will be cognized in terms of one of the five levels a-e:`,-1),l[5]||=r(`blockquote`,null,[r(`p`,null,`Level a: C C Level b: C G C Level c: C E G C Level d: C D E F G A B C Level e: C D♭ D E♭ E F F♯ G A♭ A B♭ B C`),r(`p`,null,`(Lerdahl 1992, 113)`)],-1),l[6]||=r(`p`,null,`Note that Lerdahl's model is meant to be cyclical, with its right edge identical to its left. One could therefore display Lerdahl's graph as a series of five concentric circles representing the five melodic "alphabets." In this way one could unite the circular representation depicted at the beginning of this article with Lerdahl's flat two-dimensional representation depicted above.`,-1),l[7]||=r(`p`,null,`According to David Kopp (2002, 1), "Harmonic space, or tonal space as defined by Fred Lerdahl, is the abstract nexus of possible normative harmonic connections in a system, as opposed to the actual series of temporal connections in a realized work, linear or otherwise."`,-1)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};